using UnityEngine;using UnityEngine.UI;using IdleIntelligence.Core;
namespace IdleIntelligence.Runtime {
 public sealed class ModelLoadout:MonoBehaviour {
  public RectTransform Network,Universal;public Image Core;public Text Name,Stats;GameRuntime game;GameState observed;float feedback=1;double receiptAt=-1000;bool changedIncome,changedData;public static readonly Vector2[] Positions={new Vector2(.14f,.82f),new Vector2(.14f,.5f),new Vector2(.14f,.18f),new Vector2(.86f,.82f),new Vector2(.86f,.5f),new Vector2(.86f,.18f)};
  public void Initialize(GameRuntime runtime){game=runtime;Name.transform.SetParent(transform,false);Name.transform.SetSiblingIndex(0);var nameSize=Name.gameObject.AddComponent<LayoutElement>();nameSize.minHeight=nameSize.preferredHeight=28;Name.fontSize=16;Name.resizeTextForBestFit=true;Name.resizeTextMinSize=12;Name.resizeTextMaxSize=16;var networkSize=Network.GetComponent<LayoutElement>();networkSize.minHeight=networkSize.preferredHeight=320;Core.rectTransform.sizeDelta=Vector2.one*118;Core.raycastTarget=true;var training=Core.gameObject.GetComponent<Button>()??Core.gameObject.AddComponent<Button>();training.onClick.AddListener(()=>game.UserShow("training"));var summary=WorkshopUIFactory.Horizontal("LoadoutSummary",transform,44);summary.GetComponent<HorizontalLayoutGroup>().spacing=8;Stats.transform.SetParent(summary.transform,false);var statSize=Stats.GetComponent<LayoutElement>();statSize.flexibleWidth=1;statSize.minWidth=0;statSize.minHeight=statSize.preferredHeight=44;Stats.resizeTextForBestFit=true;Stats.resizeTextMinSize=11;Stats.resizeTextMaxSize=12;var details=WorkshopUIFactory.Button("LoadoutBonuses",summary.transform,UiLocalizedText.Translate("Details",game.State.Settings.language),()=>game.WorkshopView.OpenBonuses());var detailsSize=details.GetComponent<LayoutElement>();detailsSize.minWidth=detailsSize.preferredWidth=88;detailsSize.flexibleWidth=0;detailsSize.minHeight=detailsSize.preferredHeight=44;details.GetComponent<Image>().color=Color.clear;}
  public void Receipt(bool reduced,bool incomeChanged=false,bool dataChanged=false){changedIncome=incomeChanged;changedData=dataChanged;feedback=reduced?1:0;receiptAt=ReceiptMotion.Now-(reduced?1:0);}
  string Tint(string value,bool changed)=>changed&&feedback<.6f?"<color=#38EEA0>"+value+"</color>":value;
  void LateUpdate(){if(game==null)return;feedback=ReceiptMotion.Age(receiptAt);var s=game.State;if(ReferenceEquals(observed,s)&&feedback>=.6f)return;observed=s;Name.text=s.Retention.aiName+" · Lv. "+s.ModelLevel;Stats.text=Tint(NumberFormatting.Format(Game.Income(s),s.Settings.numberFormat,s.Settings.language)+" C/s",changedIncome)+" · "+Tint(NumberFormatting.Format(Game.DataRate(s),s.Settings.numberFormat,s.Settings.language)+" D/s",changedData);Core.color=feedback<.28f?Color.Lerp(GameTheme.Accent,Color.white,feedback/.28f):Color.white;Stats.color=GameTheme.Text;Core.rectTransform.anchoredPosition=new Vector2(0,feedback<.28f?Mathf.Sin(feedback/.28f*Mathf.PI)*3:0);}
 }
}
